package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;

final class RecordCollaborationAcceptance {
 static void limits(WorkflowSupport h)throws Exception{
  String record=seed(h);var records=new ArrayList<String>();String reader;try(var db=h.store.open()){PlatformFoundationTest.bind(db);reader=RecordAccess.owner(db,"ActivityReader");String password=db.one("SELECT password FROM os_user WHERE name='admin'").get("password").toString();for(int n=0;n<500;n++){db.update("INSERT INTO os_user(user_id,name,role,password) VALUES(?,?,'reader',?)",id(),"CapUser"+n,password);records.add(Service.create(db,"incident",map("short_description","Capacity record "+n),"admin").get("sys_id").toString());}for(String id:records.subList(0,100))db.update("INSERT INTO os_record_follow(record_id,user_id,revision,definition) VALUES(?,?,1,?)",id,reader,JSON.writeValueAsString(map("categories",List.of("changes"))));db.connection.commit();}assertEquals(400,h.json("POST",route(record),subscription(0,List.of("changes")),auth("ActivityReader")).statusCode());
  try(var db=h.store.open()){db.update("DELETE FROM os_record_follow");db.update("INSERT INTO os_record_follow(record_id,user_id,revision,definition) SELECT ?,user_id,1,? FROM os_user WHERE name LIKE 'CapUser%' LIMIT 100",record,JSON.writeValueAsString(map("categories",List.of("changes"))));db.connection.commit();}assertEquals(400,h.json("POST",route(record),subscription(0,List.of("changes")),auth("ActivityReader")).statusCode());
  try(var db=h.store.open()){db.update("DELETE FROM os_record_follow");for(int n=0;n<500;n++)db.update("INSERT INTO os_record_follow(record_id,user_id,revision,definition) SELECT ?,user_id,1,? FROM os_user WHERE name LIKE 'CapUser%' AND (CAST(SUBSTR(name,8) AS INTEGER)+?)%500<100",records.get(n),JSON.writeValueAsString(map("categories",List.of("changes"))),n);assertEquals(50000,db.count("SELECT COUNT(*) FROM os_record_follow"));db.connection.commit();}assertEquals(400,h.json("POST",route(record),subscription(0,List.of("changes")),auth("ActivityReader")).statusCode());
  try(var db=h.store.open()){db.update("INSERT INTO os_collaboration_post(record_id,actor_id,request_key,event_sequence,fingerprint,created) SELECT ?,a.user_id,b.user_id,1,'capacity',? FROM (SELECT user_id FROM os_user WHERE name LIKE 'CapUser%' LIMIT 10) a CROSS JOIN (SELECT user_id FROM os_user WHERE name LIKE 'CapUser%' LIMIT 100) b",record,now());db.connection.commit();}assertEquals(400,h.json("POST",route(record),journal("comment","Per-record capacity",List.of()),auth("admin")).statusCode());
  try(var db=h.store.open()){db.update("DELETE FROM os_collaboration_post");db.update("INSERT INTO os_collaboration_post(record_id,actor_id,request_key,event_sequence,fingerprint,created) SELECT record_id,?,user_id,1,'capacity',? FROM os_record_follow",RecordAccess.owner(db,"admin"),now());assertEquals(50000,db.count("SELECT COUNT(*) FROM os_collaboration_post"));db.connection.commit();}assertEquals(400,h.json("POST",route(record),journal("comment","Global capacity",List.of()),auth("admin")).statusCode());
 }
 static final String DIRECTORY="/api/openservice/me/subscriptions";
 static String route(String record){return "/api/openservice/collaboration/incident/"+record;}
 static Map<String,Object> result(java.net.http.HttpResponse<byte[]> r,int status){return CatalogueQuestionsAcceptance.result(r,status);}
 static Map<String,Object> post(WorkflowSupport h,String id,Object body,String user,int status)throws Exception{return result(h.json("POST",route(id),body,auth(user)),status);}
 static Map<String,Object> subscription(int revision,Object categories){return map("operation","subscribe","revision",revision,"categories",categories);}
 static Map<String,Object> journal(String kind,String message,Object mentions){return map("operation","post","kind",kind,"body",message,"mentions",mentions,"key",id());}
 static String seed(WorkflowSupport h)throws Exception{h.account("ActivityReader","reader");h.account("ActivityAgent","agent");h.account("ActivityRequester","requester");return h.add("incident").get("sys_id").toString();}
 static List<Map<String,Object>> notices(WorkflowSupport h,String user)throws Exception{try(var db=h.store.open()){return db.all("SELECT * FROM os_notice WHERE user_id=? ORDER BY created_at,notice_id",db.one("SELECT user_id FROM os_user WHERE name=?",user).get("user_id"));}}
 static void change(WorkflowSupport h,String record,String body)throws Exception{assertEquals(200,h.json("PATCH","/api/now/table/incident/"+record,map("description",body),auth("admin")).statusCode());}
 static void run(WorkflowSupport h)throws Exception{
  String record=seed(h);post(h,record,subscription(0,List.of("changes","comments")),"ActivityReader",200);post(h,record,subscription(0,List.of("comments","notes")),"ActivityAgent",200);post(h,record,subscription(0,List.of("changes","comments","notes")),"admin",200);change(h,record,"Private field text must not appear in notice");assertEquals(1,notices(h,"ActivityReader").size());assertTrue(notices(h,"ActivityAgent").isEmpty());assertTrue(notices(h,"admin").isEmpty());String notice=notices(h,"ActivityReader").getFirst().get("notice_id").toString();assertFalse(JSON.writeValueAsString(notices(h,"ActivityReader")).contains("Private field"));assertEquals("/record/incident/"+record+"/collaboration",result(h.get("/api/openservice/notifications/"+notice+"/context",auth("ActivityReader")),200).get("url"));assertEquals(404,h.get("/api/openservice/notifications/"+notice+"/context",auth("ActivityAgent")).statusCode());
  var input=journal("comment","Shared evidence <script>not executed</script>",List.of("ActivityReader","ActivityAgent"));var first=post(h,record,input,"admin",200);assertEquals(first.get("receipt"),post(h,record,input,"admin",200).get("receipt"));assertEquals(2,notices(h,"ActivityReader").size());assertEquals(1,notices(h,"ActivityAgent").size());assertTrue(notices(h,"ActivityAgent").getFirst().get("message").toString().contains("mentioned"));assertFalse(JSON.writeValueAsString(notices(h,"ActivityAgent")).contains("Shared evidence"));post(h,record,journal("note","Private staff note",List.of("ActivityAgent")),"admin",200);assertEquals(2,notices(h,"ActivityAgent").size());assertEquals(2,notices(h,"ActivityReader").size());assertFalse(JSON.writeValueAsString(result(h.get(route(record),auth("ActivityReader")),200)).contains("Private staff note"));assertTrue(JSON.writeValueAsString(result(h.get(route(record),auth("ActivityAgent")),200)).contains("Private staff note"));
  new Store(h.environment);assertEquals(first.get("receipt"),post(h,record,input,"admin",200).get("receipt"));assertEquals(1,objects(result(h.get(DIRECTORY,auth("ActivityReader")),200).get("subscriptions")).size());post(h,record,journal("comment","Reader reply @ActivityAgent stays plain text",List.of()),"ActivityReader",200);assertEquals(2,notices(h,"ActivityReader").size());assertEquals(3,notices(h,"ActivityAgent").size());assertEquals(1,notices(h,"admin").size());try(var db=h.store.open()){assertEquals(3,db.count("SELECT COUNT(*) FROM os_collaboration_post"));assertEquals(3,db.count("SELECT COUNT(*) FROM os_event WHERE record_id=? AND action IN ('comment','note')",record));}
 }
 static void boundaries(WorkflowSupport h)throws Exception{
  String record=seed(h);assertEquals(401,h.get(route(record),null).statusCode());assertEquals(404,h.get(route(id()),auth("admin")).statusCode());assertEquals(400,h.get(route(record)+"?q=x",auth("admin")).statusCode());assertEquals(405,h.json("PUT",route(record),map(),auth("admin")).statusCode());String form="/record/incident/"+record+"/collaboration";assertEquals(403,h.form(form,map(),auth("admin")).statusCode());assertEquals(200,h.get(form,auth("admin")).statusCode());assertEquals(400,h.get(DIRECTORY+"?q=x",auth("admin")).statusCode());assertEquals(405,h.json("PUT",DIRECTORY,map(),auth("admin")).statusCode());assertEquals(200,h.get("/account/subscriptions",auth("admin")).statusCode());
  for(var body:List.of(map(),map("operation","bad"),subscription(0,"bad"),subscription(0,List.of()),subscription(0,List.of("changes","comments","notes","extra")),subscription(0,List.of("changes","changes")),subscription(0,List.of("unknown")),subscription(0,List.of(1)),map("operation","subscribe","revision",0,"categories",List.of("changes"),"extra",true)))assertEquals(400,h.json("POST",route(record),body,auth("admin")).statusCode());assertEquals(403,h.json("POST",route(record),subscription(0,List.of("notes")),auth("ActivityReader")).statusCode());post(h,record,subscription(0,List.of("changes")),"ActivityReader",200);assertEquals(409,h.json("POST",route(record),subscription(0,List.of("comments")),auth("ActivityReader")).statusCode());post(h,record,subscription(1,List.of("comments")),"ActivityReader",200);
  for(var patch:List.of(map("kind","unknown"),map("body",""),map("body","x".repeat(4001)),map("key","invalid"),map("mentions","scalar"),map("mentions",Collections.nCopies(11,"ActivityAgent")),map("mentions",List.of("ActivityAgent","ActivityAgent")),map("mentions",List.of(12)),map("extra",true))){var body=journal("comment","Message",List.of());body.putAll(patch);assertEquals(400,h.json("POST",route(record),body,auth("admin")).statusCode());}assertEquals(403,h.json("POST",route(record),journal("note","No private note",List.of()),auth("ActivityReader")).statusCode());var input=journal("comment","Original",List.of());post(h,record,input,"admin",200);input.put("body","Conflicting body");assertEquals(409,h.json("POST",route(record),input,auth("admin")).statusCode());
  assertEquals(400,h.protectedForm(form,map("operation","subscribe","revision","0","changes","false"),auth("admin")).statusCode());assertEquals(200,h.protectedForm(form,map("operation","subscribe","revision","0","changes","true","comments","true","notes","true"),auth("admin")).statusCode());assertEquals(200,h.protectedForm(form,map("operation","post","kind","comment","body","Form comment","mentions","ActivityReader\nActivityAgent","key",id()),auth("admin")).statusCode());assertEquals(200,h.protectedForm(form,map("operation","post","kind","comment","body","Form without mention","mentions","","key",id()),auth("admin")).statusCode());
  assertEquals(400,h.protectedForm(form,map("operation","post","kind","comment","body","Missing required mentions field","key",id()),auth("admin")).statusCode());
  for(var body:List.of(map(),map("record_id","bad"),map("record_id",record,"extra",1)))assertEquals(400,h.json("POST",DIRECTORY,body,auth("ActivityReader")).statusCode());assertEquals(200,h.json("POST",DIRECTORY,map("record_id",record),auth("ActivityReader")).statusCode());assertEquals(200,h.json("POST",DIRECTORY,map("record_id",record),auth("ActivityReader")).statusCode());assertEquals(302,h.protectedForm("/account/subscriptions",map("record_id",record),auth("admin")).statusCode());
 }
 static void currentAuthority(WorkflowSupport h)throws Exception{
  String record=seed(h);post(h,record,subscription(0,List.of("changes","comments")),"ActivityReader",200);post(h,record,subscription(0,List.of("notes")),"ActivityAgent",200);for(String name:List.of("UnknownUser","ActivityRequester"))assertEquals(400,h.json("POST",route(record),journal("comment","Rejected all recipients",List.of("ActivityReader",name)),auth("admin")).statusCode());assertEquals(400,h.json("POST",route(record),journal("note","Staff only",List.of("ActivityReader")),auth("admin")).statusCode());assertTrue(notices(h,"ActivityReader").isEmpty());
  try(var db=h.store.open()){db.update("UPDATE os_user SET active=0 WHERE name='ActivityReader'");db.connection.commit();}assertEquals(400,h.json("POST",route(record),journal("comment","Inactive recipient",List.of("ActivityReader")),auth("admin")).statusCode());change(h,record,"Inactive follower");assertTrue(notices(h,"ActivityReader").isEmpty());try(var db=h.store.open()){db.update("UPDATE os_user SET active=1 WHERE name='ActivityReader'");db.connection.commit();}
  assertEquals(200,h.json("POST","/api/openservice/me/notifications",map("enabled",false),auth("ActivityReader")).statusCode());post(h,record,journal("comment","Preference suppressed",List.of("ActivityReader")),"admin",200);assertTrue(notices(h,"ActivityReader").isEmpty());assertEquals(200,h.json("POST","/api/openservice/me/notifications",map("enabled",true),auth("ActivityReader")).statusCode());change(h,record,"Current access");String notice=notices(h,"ActivityReader").getFirst().get("notice_id").toString();ProblemInvestigationsAcceptance.access(h,"incident",record,"private",FieldDispatchAcceptance.uid(h,"admin"));change(h,record,"Revoked access");assertEquals(1,notices(h,"ActivityReader").size());assertEquals(404,h.get("/api/openservice/notifications/"+notice+"/context",auth("ActivityReader")).statusCode());var unavailable=objects(result(h.get(DIRECTORY,auth("ActivityReader")),200).get("subscriptions")).getFirst();assertEquals(false,unavailable.get("available"));assertEquals("Unavailable record",unavailable.get("label"));assertEquals(400,h.json("POST",route(record),journal("comment","No grant by mention",List.of("ActivityReader")),auth("admin")).statusCode());assertEquals(200,h.json("POST",DIRECTORY,map("record_id",record),auth("ActivityReader")).statusCode());assertTrue(objects(result(h.get(DIRECTORY,auth("ActivityReader")),200).get("subscriptions")).isEmpty());
  ProblemInvestigationsAcceptance.access(h,"incident",record,"workspace","");post(h,record,journal("note","Before role change",List.of("ActivityAgent")),"admin",200);String noteNotice=notices(h,"ActivityAgent").getFirst().get("notice_id").toString();try(var db=h.store.open()){db.update("UPDATE os_user SET role='reader' WHERE name='ActivityAgent'");db.connection.commit();}post(h,record,journal("note","After role change",List.of()),"admin",200);assertEquals(1,notices(h,"ActivityAgent").size());assertEquals(404,h.get("/api/openservice/notifications/"+noteNotice+"/context",auth("ActivityAgent")).statusCode());try(var db=h.store.open()){db.update("UPDATE os_user SET role='agent' WHERE name='ActivityAgent'");db.connection.commit();}assertEquals(200,h.get("/api/openservice/notifications/"+noteNotice+"/context",auth("ActivityAgent")).statusCode());assertEquals(204,h.json("DELETE","/api/now/table/incident/"+record,map(),auth("admin")).statusCode());assertEquals(404,h.get("/api/openservice/notifications/"+noteNotice+"/context",auth("ActivityAgent")).statusCode());
 }
 static void fieldAndParentScope(WorkflowSupport h)throws Exception{
  String record=seed(h);Map<String,Object> original;try(var db=h.store.open()){original=Service.schema(db,"incident");}var schema=new LinkedHashMap<>(original);schema.put("field_rules",map("comments",map("type","string","read_roles",List.of("admin")),"work_notes",map("type","string","read_roles",List.of("admin"))));ReferencePickerAcceptance.writeSchema(h,"incident",schema);assertEquals(403,h.json("POST",route(record),subscription(0,List.of("comments")),auth("ActivityReader")).statusCode());assertEquals(403,h.json("POST",route(record),journal("comment","Hidden comment",List.of()),auth("ActivityReader")).statusCode());assertEquals(403,h.json("POST",route(record),subscription(0,List.of("notes")),auth("ActivityAgent")).statusCode());var page=result(h.get(route(record),auth("ActivityAgent")),200);assertEquals(false,page.get("can_note"));assertEquals(false,page.get("can_comment"));assertTrue(objects(page.get("entries")).isEmpty());ReferencePickerAcceptance.writeSchema(h,"incident",original);
  post(h,record,subscription(0,List.of("comments","notes")),"ActivityAgent",200);post(h,record,journal("note","Allowed note",List.of("ActivityAgent")),"admin",200);String notice=notices(h,"ActivityAgent").getFirst().get("notice_id").toString();ReferencePickerAcceptance.writeSchema(h,"incident",schema);post(h,record,journal("note","Restricted note",List.of()),"admin",200);assertEquals(1,notices(h,"ActivityAgent").size());assertEquals(404,h.get("/api/openservice/notifications/"+notice+"/context",auth("ActivityAgent")).statusCode());schema=new LinkedHashMap<>(original);schema.put("record_roles",map("update",List.of("admin")));ReferencePickerAcceptance.writeSchema(h,"incident",schema);assertEquals(false,result(h.get(route(record),auth("ActivityAgent")),200).get("can_note"));assertEquals(403,h.json("POST",route(record),journal("note","Denied write",List.of()),auth("ActivityAgent")).statusCode());ReferencePickerAcceptance.writeSchema(h,"incident",original);
  String parent=h.add("incident").get("sys_id").toString();try(var db=h.store.open()){db.update("INSERT INTO os_record_scope(record_id,parent_id,revision) VALUES(?,?,1)",record,parent);db.connection.commit();}post(h,record,journal("comment","Before parent revocation",List.of("ActivityReader")),"admin",200);assertEquals(1,notices(h,"ActivityReader").size());ProblemInvestigationsAcceptance.access(h,"incident",parent,"private",FieldDispatchAcceptance.uid(h,"admin"));assertEquals(400,h.json("POST",route(record),journal("comment","Parent revoked",List.of("ActivityReader")),auth("admin")).statusCode());assertEquals(404,h.get(route(record),auth("ActivityReader")).statusCode());
  try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);db.employeePortal=true;var user=db.one("SELECT user_id,name,role,active FROM os_user WHERE name='ActivityReader'");assertFalse(RecordCollaboration.recipient(db,user,"incident",record,"comments"));assertEquals(actor,db.viewerId);assertEquals("admin",db.viewerRole);assertTrue(db.employeePortal);assertFalse(RecordCollaboration.recipient(db,user,"missing",record,"comments"));}
  schema=new LinkedHashMap<>(original);schema.put("record_roles",map("read",List.of("admin")));ReferencePickerAcceptance.writeSchema(h,"incident",schema);post(h,record,journal("note","Table read denial",List.of()),"admin",200);assertEquals(2,notices(h,"ActivityAgent").size());ReferencePickerAcceptance.writeSchema(h,"incident",original);
 }
 static void concurrencyAndRollback(WorkflowSupport h)throws Exception{
  String record=seed(h);post(h,record,subscription(0,List.of("comments")),"ActivityReader",200);var input=journal("comment","Concurrent publication",List.of("ActivityReader"));try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var first=pool.submit(()->post(h,record,input,"admin",200));var second=pool.submit(()->post(h,record,input,"admin",200));assertEquals(first.get().get("receipt"),second.get().get("receipt"));}assertEquals(1,notices(h,"ActivityReader").size());try(var db=h.store.open()){assertEquals(1,db.count("SELECT COUNT(*) FROM os_collaboration_post"));assertEquals(1,db.count("SELECT COUNT(*) FROM os_event WHERE record_id=? AND action='comment'",record));db.update("CREATE UNIQUE INDEX fixture_post_failure ON os_collaboration_post(record_id)");db.connection.commit();}assertEquals(500,h.json("POST",route(record),journal("comment","Must roll back",List.of("ActivityReader")),auth("admin")).statusCode());assertEquals(1,notices(h,"ActivityReader").size());try(var db=h.store.open()){assertEquals(1,db.count("SELECT COUNT(*) FROM os_event WHERE record_id=? AND action='comment'",record));db.update("DROP INDEX fixture_post_failure");db.connection.commit();}
  try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var one=pool.submit(()->h.json("POST",route(record),subscription(1,List.of("changes")),auth("ActivityReader")).statusCode());var two=pool.submit(()->h.json("POST",route(record),subscription(1,List.of("notes")),auth("ActivityReader")).statusCode());assertEquals(200,one.get());assertTrue(Set.of(403,409).contains(two.get()));}
 }
 static void requester(WorkflowSupport h)throws Exception{
  String record=seed(h);String route=route(record);assertEquals(404,h.json("POST",route,subscription(0,List.of("comments")),auth("ActivityRequester")).statusCode());try(var db=h.store.open()){db.update("INSERT INTO os_requester_record(record_id,user_id) VALUES(?,?)",record,RecordAccess.owner(db,"ActivityRequester"));db.connection.commit();}post(h,record,subscription(0,List.of("changes","comments")),"ActivityRequester",200);post(h,record,journal("comment","Requester journal",List.of("ActivityAgent")),"ActivityRequester",200);post(h,record,journal("comment","Staff reply",List.of("ActivityRequester")),"ActivityAgent",200);assertEquals(1,notices(h,"ActivityRequester").size());assertEquals(403,h.json("POST",route,journal("note","No staff entry",List.of()),auth("ActivityRequester")).statusCode());try(var db=h.store.open()){db.update("DELETE FROM os_requester_record WHERE record_id=?",record);db.connection.commit();}assertEquals(404,h.get(route,auth("ActivityRequester")).statusCode());assertEquals(200,h.json("POST",DIRECTORY,map("record_id",record),auth("ActivityRequester")).statusCode());
 }
}
